css:
/* Container settings */
.switch-3d-cyan {
  --w: 110px;
  --h: 40px;
  --knob-size: 20px;
  --offset: 10px;

  /* --- COLORS --- */
  --cyan: #00ffff; /* The only accent color now */
  --white-glow: #ffffff;
  --bg-off: #1a2a2a; /* Dark Gray-ish */
  --bg-on: #0f0f1a; /* Dark Blue-ish */

  /* Calculations */
  --half-size: calc(var(--knob-size) / 2);

  position: relative;
  display: inline-block;
  width: var(--w);
  height: var(--h);
  cursor: pointer;
}

.switch-input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The Track */
.switch-track {
  position: absolute;
  inset: 0;
  background-color: var(--bg-off);
  border-radius: var(--h);
  border: 1px solid #444; /* Neutral border when OFF */
  transition: all 0.5s ease;
  overflow: hidden;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
}

/* --- TEXT SETTINGS (White & Glowing) --- */
.track-text {
  position: absolute;
  font-family: "Arial", sans-serif;
  font-size: 13px;
  font-weight: 800;
  color: var(--white-glow);
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.8);
  transition:
    opacity 0.4s ease,
    transform 0.4s ease;
  pointer-events: none;
  white-space: nowrap;
}

/* Position for "View 3D" (Visible initially) */
.text-3d {
  left: 40px;
  opacity: 1;
}

/* Position for "View 2D" (Hidden initially) */
.text-2d {
  left: 15px;
  opacity: 0;
  transform: translateX(-10px);
}

/* The Knob Wrapper */
.switch-knob {
  position: absolute;
  top: var(--offset);
  left: var(--offset);
  width: var(--knob-size);
  height: var(--knob-size);
  perspective: 1200px;
  pointer-events: none;
  transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  z-index: 2;
}

/* The Cube - ALWAYS SPINNING */
.cube {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  animation: spin 3s infinite linear;
}

/* Cube Faces - ALWAYS CYAN NOW */
.face {
  position: absolute;
  width: 100%;
  height: 100%;
  /* Cyan tint */
  background: rgba(0, 255, 255, 0.1);
  /* Cyan border */
  border: 1px solid var(--cyan);
  /* Cyan glow */
  box-shadow:
    0 0 4px var(--cyan),
    inset 0 0 4px var(--cyan);
  opacity: 0.8;
  backface-visibility: visible;
  transition: all 0.5s ease;
}

.front {
  transform: translateZ(var(--half-size));
}
.back {
  transform: rotateY(180deg) translateZ(var(--half-size));
}
.right {
  transform: rotateY(90deg) translateZ(var(--half-size));
}
.left {
  transform: rotateY(-90deg) translateZ(var(--half-size));
}
.top {
  transform: rotateX(90deg) translateZ(var(--half-size));
}
.bottom {
  transform: rotateX(-90deg) translateZ(var(--half-size));
}

/* --- CHECKED STATE --- */

/* 1. Move knob */
.switch-input:checked ~ .switch-track .switch-knob {
  transform: translateX(
    calc(var(--w) - var(--knob-size) - (var(--offset) * 2))
  );
}

/* 2. TEXT SWAP LOGIC */
.switch-input:checked ~ .switch-track .text-3d {
  opacity: 0;
  transform: translateX(10px);
}
.switch-input:checked ~ .switch-track .text-2d {
  opacity: 1;
  transform: translateX(0);
}

/* 3. Change Background & Border */
.switch-input:checked ~ .switch-track {
  background-color: var(--bg-on);
  border-color: var(--cyan); /* Border glows cyan only when ON */
  box-shadow: 0 0 10px rgba(0, 255, 255, 0.3);
}

/* 4. Intensify Cube Glow when ON */
.switch-input:checked ~ .switch-track .face {
  background: rgba(0, 255, 255, 0.15);
  box-shadow:
    0 0 8px var(--cyan),
    inset 0 0 8px var(--cyan);
}

@keyframes spin {
  0% {
    transform: rotateX(0deg) rotateY(0deg);
  }
  100% {
    transform: rotateX(360deg) rotateY(360deg);
  }
}
